import{_ as a,o as t,c as o,a3 as d}from"./chunks/framework.DMtjdCb-.js";const i="/help/assets/offline-update.ja.CNj7_48G.png",k=JSON.parse('{"title":"9. 更新とバックアップ","description":"","frontmatter":{},"headers":[],"relativePath":"ja/updates.md","filePath":"ja/updates.md"}'),c={name:"ja/updates.md"};function l(n,e,r,s,h,p){return t(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="_9-更新とバックアップ" tabindex="-1">9. 更新とバックアップ <a class="header-anchor" href="#_9-更新とバックアップ" aria-label="Permalink to &quot;9. 更新とバックアップ&quot;">​</a></h1><p>アプリを更新しても、設定・作品情報・視聴記録は引き継ぎます。Bangumi Archive は作品資料で、アプリのバージョンとは別に更新します。</p><h2 id="オンライン更新" tabindex="-1">オンライン更新 <a class="header-anchor" href="#オンライン更新" aria-label="Permalink to &quot;オンライン更新&quot;">​</a></h2><ol><li><strong>設定 → 更新の確認</strong> を開きます。</li><li>新しいバージョンと変更内容を確認します。</li><li>画面で利用できる更新操作を実行し、再起動を待って画面を更新します。</li><li>実行中のバージョンを確認します。Docker は新しいイメージによる再作成でも更新できます。</li></ol><h2 id="オフライン更新パッケージをアップロードする" tabindex="-1">オフライン更新パッケージをアップロードする <a class="header-anchor" href="#オフライン更新パッケージをアップロードする" aria-label="Permalink to &quot;オフライン更新パッケージをアップロードする&quot;">​</a></h2><p>0.5.1 以降は同じページからアップロードできます。</p><ol><li>ダウンロード可能な機器で、導入方法に対応する <code>.anm-update.zip</code> を取得します。</li><li><strong>設定 → 更新の確認</strong> でファイルを選んでアップロードします。</li><li>検証・インストール・再起動を待ち、バージョンを確認します。</li></ol><p><img src="'+i+'" alt="オフライン更新：導入方法に合うパッケージを選択" loading="lazy"></p><table tabindex="0"><thead><tr><th>導入方法</th><th>更新パッケージ</th></tr></thead><tbody><tr><td>Windows 版</td><td><code>AnimeMachine-バージョン-windows.anm-update.zip</code></td></tr><tr><td>Docker</td><td><code>AnimeMachine-バージョン-docker.anm-update.zip</code></td></tr></tbody></table><p>通常の <code>release-windows.zip</code> は展開用の完全パッケージ、Docker の <code>tar.gz</code> はオフラインイメージです。アップロード用とは用途が異なります。形式や検証結果が不正な場合は、現在のバージョンを引き続き使用します。</p><h2 id="docker-0-5-0-から-0-5-1-へ" tabindex="-1">Docker 0.5.0 から 0.5.1 へ <a class="header-anchor" href="#docker-0-5-0-から-0-5-1-へ" aria-label="Permalink to &quot;Docker 0.5.0 から 0.5.1 へ&quot;">​</a></h2><p>オフラインイメージは <a href="https://github.com/kyupi-git/animemachine/releases/latest" target="_blank" rel="noreferrer">Releases</a> から取得できます。Intel / AMD は <code>amd64</code>、ARM は <code>arm64</code> を選びます。</p><p>0.5.0 にはアップロード欄がないため、先にローカルイメージから更新します。</p><ol><li><code>AnimeMachine-0.5.1-docker-linux-amd64.tar.gz</code> を NAS へ転送します。Intel・AMD 用のため、ARM 機器は対応するイメージを選びます。</li><li>ターミナルで読み込みます。</li></ol><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> load</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> AnimeMachine-0.5.1-docker-linux-amd64.tar.gz</span></span></code></pre></div><ol start="3"><li>プロジェクトの <code>.env</code> に <code>ANM_IMAGE=animemachine:0.5.1</code> を設定します。標準のフル構成は <code>TORRENT_COLLECTOR_IMAGE=animemachine:0.5.1</code> も指定します。</li><li>同じ場所で <code>docker compose up -d --pull never</code> を実行し、ページとバージョンを確認します。</li></ol><p>独自の Compose にイメージ名を直接指定している場合は、対象サービスの <code>image</code> を変更します。マウント、環境設定、データの場所は引き継ぎます。</p><h2 id="pc-版を手動で置き換える" tabindex="-1">PC 版を手動で置き換える <a class="header-anchor" href="#pc-版を手動で置き換える" aria-label="Permalink to &quot;PC 版を手動で置き換える&quot;">​</a></h2><p>旧版を終了し、新版を別フォルダーへ展開します。旧版の <code>config.json</code>、<code>.env.local</code>（ある場合）、<code>data</code> 全体を新しいフォルダーへコピーして起動します。動画を別の場所に保存している場合は、同じパスを引き続き使用します。</p><h2 id="バックアップするもの" tabindex="-1">バックアップするもの <a class="header-anchor" href="#バックアップするもの" aria-label="Permalink to &quot;バックアップするもの&quot;">​</a></h2><p>AnimeMachine を停止してから設定と <code>data</code> をバックアップします。動画は普段の保存先のバックアップ方法を使用します。</p><table tabindex="0"><thead><tr><th>導入方法</th><th>保管するもの</th></tr></thead><tbody><tr><td>PC 版</td><td><code>config.json</code>、<code>.env.local</code>（ある場合）、<code>data</code></td></tr><tr><td>Docker</td><td><code>compose.yaml</code>、<code>.env</code>（ある場合）、<code>config</code>、<code>data</code>、独自のマウント設定</td></tr></tbody></table><p>復元時は同じ対応パスとアカウントデータを使用します。<code>initial-admin.txt</code> やサービスのパスワードファイルもアカウント情報として保管します。</p>',23)])])}const u=a(c,[["render",l]]);export{k as __pageData,u as default};
